// Evaluate the the WhatsApp gateway status response. TODO(heartbeat-endpoint): adjust
// the field checks below to the WhatsApp gateway's actual response shape once the real
// endpoint is filled in -- this covers the common shapes, but VERIFY against
// one real response before trusting it. Fails CLOSED: anything that doesn't
// positively look connected counts as down.
const r = $input.first().json;
const candidates = [r.status, r.state, r.data && r.data.status, r.data && r.data.state, r.session && r.session.status];
const looksConnected = candidates.some(v => typeof v === 'string' && /^(connected|open|online|authenticated|working)$/i.test(v));
return { json: {
  down: !looksConnected,
  alertText: looksConnected ? '' : ('\ud83d\udea8 the WhatsApp gateway session looks DOWN (status response did not report connected). The bot may be silent \u2014 the product owner may need to rescan the QR via disconnect/reconnect. Raw status snippet: ' + JSON.stringify(r).substring(0, 300))
} };

// The health check itself failed (timeout / DNS / non-2xx). That's an
// alert in its own right -- a check that can't run tells us nothing, and
// silence is exactly the failure mode this workflow exists to catch.
const e = $input.first().json;
return { json: {
  down: true,
  alertText: '\u26a0\ufe0f the WhatsApp gateway health check FAILED to run (endpoint unreachable or errored) \u2014 cannot confirm the bot is alive. Error: ' + (((e.error && e.error.message) || e.message) || 'unknown')
} };
